const fs = require('fs');
const words = JSON.parse(fs.readFileSync('words.json', 'utf8'));
const skip = new Set(['index.html','sobre.html','contato.html']);
const files = fs.readdirSync('site').filter(f => f.endsWith('.html') && !skip.has(f));
const meta = {}; const canon = {};
for (const f of files) {
  const html = fs.readFileSync('site/' + f, 'utf8');
  let h1 = (html.match(/<h1>(.*?)<\/h1>/) || [])[1];
  const tema = (html.match(/class="tema">Tema: (.*?)<\/p>/) || [])[1] || '';
  if (!h1) {
    const red = html.match(/url=([^"]+?)\.html/);
    if (red && canon[red[1] + '.html']) { canon[f] = canon[red[1] + '.html']; continue; }
    continue;
  }
  canon[f] = h1;
  meta[h1] = { tema, sin: [], ana: [] };
}
for (const f of files) {
  const w = canon[f]; if (!w || !meta[w]) continue;
  const html = fs.readFileSync('site/' + f, 'utf8');
  const grab = id => {
    const m = html.match(new RegExp('id="' + id + '">(.*?)</section>', 's'));
    if (!m) return [];
    return [...m[1].matchAll(/<a href="([^"]+)">(.*?)<\/a>/g)]
      .map(x => { let h = x[1]; if (h.includes('%')) { try { h = decodeURIComponent(h); } catch (e) {} } return canon[h]; })
      .filter(t => t && t !== w && meta[t]);
  };
  meta[w].sin = grab('sinonimos');
  meta[w].ana = grab('analogas');
}
const data = {};
for (const [w, m] of Object.entries(meta)) {
  const links = [...new Set([...(words[w] || [])])];
  data[w] = { t: m.tema, s: [...new Set(m.sin)], a: [...new Set(m.ana)], n: links.length };
}
const html = fs.readFileSync('template.html', 'utf8').replace('/*__DATA__*/', JSON.stringify(data)).replace('/*__THEMES__*/', JSON.stringify([...new Set(Object.values(data).map(d => d.t))].sort()));
fs.writeFileSync('universe/index.html', html);
console.log('built', Object.keys(data).length, 'words');


