--- parse.js ---
const fs = require('fs');
const dir = 'site';
const skip = new Set(['index.html','sobre.html','contato.html']);
const files = fs.readdirSync(dir).filter(f => f.endsWith('.html') && !skip.has(f));
const words = {}; const meta = {}; const canon = {};
for (const f of files) {
  const html = fs.readFileSync(dir + '/' + f, 'utf8');
  const h1 = (html.match(/<h1>(.*?)<\/h1>/) || [])[1];
  const tema = (html.match(/class="tema">Tema: (.*?)<\/p>/) || [])[1] || '';
  if (!h1) {
    const red = html.match(/url=([^"]+?)\.html/);
    if (red && canon[red[1] + '.html']) { canon[f] = canon[red[1] + '.html']; continue; }
    console.log('NO H1', f); continue;
  }
  canon[f] = h1;
  meta[h1] = { tema, file: f };
}
for (const f of files) {
  const w = canon[f]; if (!w) continue;
  const html = fs.readFileSync(dir + '/' + f, 'utf8');
  for (const m of html.matchAll(/<a href="([^"]+)">/g)) {
    let href = m[1];
    if (href.includes('%')) { try { href = decodeURIComponent(href); } catch (e) {} }
    if (!href.endsWith('.html') || skip.has(href)) continue;
    const t = canon[href];
    if (t && t !== w) (words[w] = words[w] || new Set()).add(t);
  }
}
const out = {};
for (const w of Object.keys(meta)) out[w] = [];
for (const [w, s] of Object.entries(words)) out[w] = [...s].sort((a, b) => a.localeCompare(b, 'pt'));
fs.writeFileSync('words.json', JSON.stringify(out, null, 1));
const pairs = new Set();
for (const [w, ws] of Object.entries(out)) for (const t of ws) { if (w === t) continue; pairs.add([w, t].sort().join('|')); }
const deg = Object.entries(out).map(([w, ws]) => [w, ws.length]).sort((a, b) => b[1] - a[1]);
fs.writeFileSync('result.json', JSON.stringify({ words: Object.keys(out).length, relations: pairs.size, most_connected: deg[0][0], most_connected_degree: deg[0][1], top10: deg.slice(0, 10) }, null, 1));
console.log('words', Object.keys(out).length, 'pairs', pairs.size, 'top', JSON.stringify(deg.slice(0, 5)));


